import {PETS,canMaterials,spendMaterials} from './economy.mjs?v=0.5';
import {regionUnlocked} from './regions.mjs?v=0.5';
export const MOUNTS={deer:{name:'Linh lộc',shape:'deer',grade:0,unlock:0,speed:13,icon:'鹿'},wolf:{name:'Ngân lang cưỡi',shape:'wolf',grade:1,unlock:1,speed:14,icon:'狼'},tiger:{name:'Bạch hổ cưỡi',shape:'tiger',grade:2,unlock:2,speed:15,icon:'虎'},dragon:{name:'Long thú',shape:'dragon',grade:4,unlock:4,speed:16,icon:'龍'}};
export const SKILL_NAMES={slash:'Long trảm',nova:'Địa chấn',mend:'Hồi nguyên'};
export const PET_EFFECTS={fox:'Linh hỏa: đánh 1 mục tiêu.',wolf:'Nanh bạc: đánh 1 mục tiêu, sát thương ×1,2.',phoenix:'Hỏa vũ: đánh tối đa 3 mục tiêu.',dragon:'Long tức: đánh tối đa 3 mục tiêu, sát thương ×1,4.',tiger:'Hổ uy: đánh 1 mục tiêu và gây choáng 0,6 giây.',crane:'Thanh phong: hồi HP cho chủ nhân.',deer:'Sinh khí: hồi HP và 6 linh lực.',turtle:'Hộ thân: khi có quái gần, miễn sát thương trong 0,5 giây mỗi nhịp.'};
export function ensureCompanions(s){s.companions??={mount:'deer',mountLevels:Object.fromEntries(Object.keys(MOUNTS).map(k=>[k,k==='deer'?1:0])),treasures:Object.fromEntries(Object.keys(PETS).map(k=>[k,0])),stance:'aggressive',skillPaths:Object.fromEntries(Object.keys(SKILL_NAMES).map(k=>[k,'balanced'])),autoSkills:{slash:true,nova:true,mend:true,dash:true}};return s;}
export function validateCompanions(s){if(s.companions===undefined)return;const c=s.companions,lv=(o,keys,max)=>o&&Object.keys(o).length===keys.length&&keys.every(k=>Number.isInteger(o[k])&&o[k]>=0&&o[k]<=max);if(!c||!Object.hasOwn(MOUNTS,c.mount)||!['aggressive','defend','passive'].includes(c.stance)||!lv(c.mountLevels,Object.keys(MOUNTS),5)||!lv(c.treasures,Object.keys(PETS),3)||!c.skillPaths||!Object.keys(SKILL_NAMES).every(k=>['balanced','power','swift'].includes(c.skillPaths[k]))||!c.autoSkills||!['slash','nova','mend','dash'].every(k=>typeof c.autoSkills[k]==='boolean'))throw Error('Pet, thú cưỡi hoặc kỹ năng không hợp lệ.');if(!c.mountLevels[c.mount])throw Error('Chưa sở hữu thú cưỡi được chọn.');for(const[k,n]of Object.entries(c.treasures))if(n&&!s.petLevels[k])throw Error('Bảo vật cần pet đã triệu hồi.');for(const[k,p]of Object.entries(c.skillPaths))if(p!=='balanced'&&s.upgrades[k]<2)throw Error('Chuyên hóa cần kỹ năng bậc 2.');}
export function mountCost(s,k){const m=MOUNTS[k];if(!m)return null;const lv=s.companions.mountLevels[k];return {gold:(lv+1)*150*(m.grade+1),materials:{herb:3+lv*2,essence:2+lv},grade:m.grade};}
export function mountReady(s,k){const m=MOUNTS[k];return !!m&&s.quest>=6&&regionUnlocked(s,m.unlock);}
export function mountSpeed(s){const c=s.companions,m=MOUNTS[c?.mount];return m&&c.mountLevels[c.mount]?m.speed+(c.mountLevels[c.mount]-1)*.6:13;}
export function mountBonus(s){const c=s.companions,m=MOUNTS[c?.mount],lv=c?.mountLevels[c.mount]||0;return {hp:lv?((lv-1)*12+m.grade*10):0,mp:0,atk:0,def:0};}
export function skillProfile(s,k){const path=s.companions?.skillPaths[k]||'balanced',lv=s.upgrades[k]||0;return {mp:{slash:18,nova:30,mend:25,dash:0,attack:0}[k],cooldown:({slash:5,nova:9,mend:13,dash:4,attack:.65}[k])*(path==='swift'?.75:1),multiplier:(k==='slash'?1.8+lv*.28:k==='nova'?1.3+lv*.25:1)*(path==='power'?1.2:1),heal:(.25+lv*.045)*(path==='power'?1.2:1),stun:1.2+lv*.25};}
export const companionActions={
 canAuto(k){return this.s.companions?.autoSkills[k]!==false;},
 setSkillPath(k,path){if(!Object.hasOwn(SKILL_NAMES,k)||!['balanced','power','swift'].includes(path)||path!=='balanced'&&this.s.upgrades[k]<2)return false;this.s.companions.skillPaths[k]=path;return true;},
 setAutoSkill(k,on){if(!Object.hasOwn(this.s.companions.autoSkills,k)||typeof on!=='boolean')return false;this.s.companions.autoSkills[k]=on;return true;},
 setPetStance(stance){if(!['aggressive','defend','passive'].includes(stance))return false;this.s.companions.stance=stance;this.spiritClock=0;return true;},
 upgradeTreasure(k){const p=PETS[k],lv=this.s.companions.treasures[k];if(!p||!this.s.petLevels[k]||lv>=3)return false;const gold=120*(lv+1),materials={gem:3*(lv+1),essence:2*(lv+1)};if(this.s.gold<gold||!canMaterials(this.s,materials,p.grade))return false;spendMaterials(this.s,materials,p.grade);this.s.gold-=gold;this.s.companions.treasures[k]++;this.say('Đã nâng bảo vật '+p.name+'.');return true;},
 upgradeMount(k){ensureCompanions(this.s);if(!mountReady(this.s,k)||this.s.companions.mountLevels[k]>=5)return false;const r=mountCost(this.s,k);if(this.s.gold<r.gold||!canMaterials(this.s,r.materials,r.grade))return false;spendMaterials(this.s,r.materials,r.grade);this.s.gold-=r.gold;this.s.companions.mountLevels[k]++;this.say('Đã huấn luyện '+MOUNTS[k].name+'.');return true;},
 chooseMount(k){ensureCompanions(this.s);if(!Object.hasOwn(MOUNTS,k)||!this.s.companions.mountLevels[k]||!mountReady(this.s,k))return false;this.s.companions.mount=k;this.mount=false;return true;},
 petPulse(){const s=this.s,k=s.spirit,lv=s.petLevels[k],c=s.companions;if(!lv||c.stance==='passive')return;const near=this.enemies.filter(e=>!e.dead&&this.unlocked(e)&&Math.hypot(s.x-e.x,s.z-e.z)<12),targets=c.stance==='defend'?near.filter(e=>e.wind>0||Math.hypot(s.x-e.x,s.z-e.z)<e.range+2):near;const treasure=c.treasures[k]||0,n=8+lv*7+treasure*5;if(k==='crane'||k==='deer'){const max=this.getStats().hp,heal=Math.min(max-s.hp,8+lv*5+treasure*4);if(heal>0){s.hp+=heal;this.emit('heal',{x:s.x,z:s.z,amount:heal});}if(k==='deer')s.mp=Math.min(this.getStats().mp,s.mp+6);return;}if(k==='turtle'){if(targets.length)this.ward=Math.max(this.ward,.5+treasure*.1);return;}const chosen=targets.sort((a,b)=>Math.hypot(s.x-a.x,s.z-a.z)-Math.hypot(s.x-b.x,s.z-b.z)).slice(0,['phoenix','dragon'].includes(k)?3:1);for(const e of chosen){this.hit(e,Math.round(n*(k==='dragon'?1.4:k==='wolf'?1.2:1)),'spirit');if(k==='tiger'&&!e.dead)e.stun=Math.max(e.stun||0,.6);}}
};
